/**
 * PowerShell Security Analyzer — client-side static analysis engine.
 *
 * Ported from Nandha Kumar M's PowerShell Security Analyzer
 * (https://github.com/nandha2001mroot/powershell-security-analyzer, MIT).
 * The upstream tool is a vanilla-JS single-page app; this module ports its
 * detection engines (signatures, detector, IOC extractor, obfuscation
 * scorer, risk engine, MITRE mapping) to typed TypeScript so the platform
 * can run the same 250-signature analysis without an iframe
 * or external fetch. 100% client-side — no execution, no server upload.
 *
 * GENERATED by scripts/fetch-powershell-analyzer.mjs — do not edit by hand.
 * Re-run the script to refresh the signature set from upstream.
 *
 * Detection results are heuristic and may contain false positives. Never
 * execute suspicious code solely based on this tool.
 */

// ─── Types ────────────────────────────────────────────────────────────

export type Severity = 'Critical' | 'High' | 'Medium' | 'Low' | 'Informational';

export type Category =
  | 'Execution'
  | 'Persistence'
  | 'Privilege Escalation'
  | 'Defense Evasion'
  | 'Credential Access'
  | 'Discovery'
  | 'Lateral Movement'
  | 'Collection'
  | 'Exfiltration'
  | 'Impact'
  | 'Network'
  | 'Process Injection'
  | 'Obfuscation';

export interface Signature {
  id: string;
  n: string;
  c: Category;
  s: Severity;
  p: string;
  d: string;
  r: string;
  m: string[];
}

export interface Finding {
  id: string;
  name: string;
  category: Category;
  severity: Severity;
  description: string;
  recommendation: string;
  mitre: string[];
  line: number;
  snippet: string;
  confidence: 'High' | 'Medium' | 'Low';
}

export interface Ioc {
  type: string;
  value: string;
  line: number;
  confidence: 'High' | 'Medium';
}

export interface ObfuscationResult {
  score: number;
  reasons: string[];
}

export interface RiskResult {
  riskScore: number;
  severity: Severity;
  maliciousScore: number;
  confidence: 'High' | 'Medium' | 'Low';
  categoryCount: number;
  mitreCount: number;
  categories: Category[];
  mitreTechniques: string[];
}

export interface AnalysisResult {
  findings: Finding[];
  iocs: Ioc[];
  obfuscation: ObfuscationResult;
  risk: RiskResult;
  summary: string;
  mitreMap: Record<string, { tactic: string; technique: string; findings: string[] }>;
}

